// Clasifica las evaluaciones y construye un único resumen.
const config = $('Configuración').first().json;
const evaluations = $input.all().map((item) => item.json.data);

const marginCheck = (e) => e.checks.find((c) => c.rule === 'MIN_GROSS_MARGIN');

const toRow = (e) => ({
  sku: e.sku,
  nombre: e.name,
  precioVenta: e.pricing.salePrice,
  costoTotal: e.pricing.totalCost,
  gananciaBruta: e.gross.profit,
  margenBrutoPct: e.gross.marginPercent,
  precioMinimoRecomendado: e.minimumRecommendedPrice,
  cumpleMargenMinimo: marginCheck(e)?.passed === true,
  elegible: e.eligible,
  motivosDescarte: e.checks.filter((c) => !c.passed).map((c) => `${c.rule}: ${c.detail}`),
  advertencias: e.warnings,
});

const rows = evaluations.map(toRow);
const elegibles = rows.filter((r) => r.elegible);
const descartados = rows.filter((r) => !r.elegible);

return [
  {
    json: {
      generadoEn: new Date().toISOString(),
      backend: config.baseUrl,
      margenObjetivoPct: config.targetMarginPercent,
      totalEvaluados: rows.length,
      cumplenMargenMinimo: rows.filter((r) => r.cumpleMargenMinimo).map((r) => r.sku),
      noCumplenMargenMinimo: rows.filter((r) => !r.cumpleMargenMinimo).map((r) => r.sku),
      totalElegibles: elegibles.length,
      totalDescartados: descartados.length,
      elegibles,
      descartados,
      nota: 'Márgenes BRUTOS: no incluyen publicidad, comisiones de Shopify/pasarela, impuestos ni devoluciones.',
    },
  },
];
